package mx.taller.security;
import org.springframework.context.annotation.*; import org.springframework.boot.CommandLineRunner; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.crypto.password.MessageDigestPasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.core.userdetails.*; import org.springframework.web.cors.*; import mx.taller.auth.*;
@Configuration public class SecurityConfig {
 @Bean CorsConfigurationSource corsConfigurationSource(@org.springframework.beans.factory.annotation.Value("${APP_CORS_ALLOWED_ORIGINS:http://localhost:5173,http://localhost:3000}") String configuredOrigins){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(java.util.Arrays.stream(configuredOrigins.split(",")).map(String::trim).filter(origin->!origin.isEmpty()).toList());c.setAllowedMethods(java.util.List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(java.util.List.of("Authorization","Content-Type"));UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}
 @Bean CommandLineRunner bootstrapAdmin(UsuarioRepository users,PasswordEncoder encoder){return args->{String email=System.getenv("BOOTSTRAP_ADMIN_EMAIL"),password=System.getenv("BOOTSTRAP_ADMIN_PASSWORD");if(email!=null&&!email.isBlank()&&password!=null&&!password.isBlank()&&!users.existsByEmailIgnoreCase(email)){Usuario u=new Usuario(email.toLowerCase(java.util.Locale.ROOT),encoder.encode(password));u.setRol(Rol.ADMINISTRADOR_TALLER);users.save(u);}};}
 @Bean UserDetailsService userDetailsService(UsuarioRepository users){return username->users.findByEmailAndActivoTrue(username.toLowerCase(java.util.Locale.ROOT)).map(u->User.withUsername(u.getEmail()).password(u.getPasswordHash()).authorities(u.getRol()==null?"ROLE_PENDIENTE":"ROLE_"+u.getRol().name()).build()).orElseThrow(()->new UsernameNotFoundException("Usuario no encontrado"));}
 @Bean SecurityFilterChain filterChain(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).authorizeHttpRequests(a->a.requestMatchers("/api/auth/registro","/api/auth/login","/api/auth/password-reset/**","/error").permitAll().anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).build();}
 // SHA-512 with per-password random salt via Spring Security's digest encoder.
 @Bean PasswordEncoder passwordEncoder(){return new MessageDigestPasswordEncoder("SHA-512");}
}
